        with pytest.raises(SubjectTokenRejected) as exc_info:
            await _post_exchange_endpoint("https://idp/token", {"grant_type": "x"}, {})
    assert exc_info.value.claims == claims
    assert "AADSTS50079" not in str(exc_info.value)


